-- Generated by scripts/duals/dual_ranker.py from transcribed dual-meet event sheets. Per-opponent placings (rank among the two teams). Id-independent; re-runnable.
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @m INT, @t INT, @pid INT, @mp INT;
SET @t = (SELECT TOP 1 Id FROM ScoringTemplates WHERE Name LIKE N'Dual Meet%' AND Deleted=0);
SET @m = (SELECT TOP 1 Id FROM Meets WHERE Name=N'2024 Norton-Springfield Double Dual' AND CAST(Date AS date)='2024-04-16');
IF @m IS NULL THROW 50050, 'meet missing', 1;
UPDATE Meets SET MeetType=2, ScoringTemplateId=@t WHERE Id=@m;
IF NOT EXISTS (SELECT 1 FROM MeetParticipants mp JOIN Schools s ON s.Id=mp.SchoolId WHERE mp.MeetId=@m AND s.Name=N'Norton' AND mp.Deleted=0) INSERT INTO MeetParticipants (MeetId, SchoolId, Gender, SortOrder) SELECT @m, Id, NULL, 0 FROM Schools WHERE Name=N'Norton';
IF NOT EXISTS (SELECT 1 FROM MeetParticipants mp JOIN Schools s ON s.Id=mp.SchoolId WHERE mp.MeetId=@m AND s.Name=N'Springfield' AND mp.Deleted=0) INSERT INTO MeetParticipants (MeetId, SchoolId, Gender, SortOrder) SELECT @m, Id, NULL, 1 FROM Schools WHERE Name=N'Springfield';
-- Norton Girls 100M Hurdles: place 2 KK Campbell 17.28
SET @pid = (SELECT TOP 1 p.Id FROM Performances p JOIN Athletes a ON a.Id=p.AthleteId JOIN Events e ON e.Id=p.EventId WHERE p.MeetId=@m AND a.FirstName=N'KK' AND a.LastName=N'Campbell' AND e.Gender=2 AND e.Name=N'100M Hurdles');
SET @mp = (SELECT TOP 1 mp.Id FROM MeetParticipants mp JOIN Schools s ON s.Id=mp.SchoolId WHERE mp.MeetId=@m AND s.Name=N'Norton' AND mp.Deleted=0);
IF @pid IS NOT NULL AND @mp IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MeetPlacings WHERE PerformanceId=@pid AND MeetParticipantId=@mp) INSERT INTO MeetPlacings (MeetId, PerformanceId, MeetParticipantId, Place, FullPoints, SplitPoints) VALUES (@m, @pid, @mp, 2, 3.0, 3.0);
